import{_ as a}from"./chunks/sh2.C2f6EkLz.js";import{_ as o,c as l,o as t,ae as i}from"./chunks/framework.BrQRMotl.js";const _=JSON.parse('{"title":"高度なモード (Advanced Mode)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/advanced_mode.md","filePath":"ja/manual/advanced_mode.md"}'),n={name:"ja/manual/advanced_mode.md"};function d(s,e,r,c,h,m){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="高度なモード-advanced-mode" tabindex="-1">高度なモード (Advanced Mode) <a class="header-anchor" href="#高度なモード-advanced-mode" aria-label="Permalink to &quot;高度なモード (Advanced Mode)&quot;">​</a></h1><p>Extended Note Block のインターフェースに <strong>「高度なモード」</strong> の入り口があります。これに入ると、より強力なオーディオレンダリング制御が解除されます。</p><p><img src="'+a+'" alt="Advanced Mode"></p><h2 id="視覚的なエンベロープ" tabindex="-1">視覚的なエンベロープ <a class="header-anchor" href="#視覚的なエンベロープ" aria-label="Permalink to &quot;視覚的なエンベロープ&quot;">​</a></h2><p>高度なモードには、2つの主要な視覚的エディタが用意されています：</p><h3 id="_1-音量エンベロープ-volume-envelope" tabindex="-1">1. 音量エンベロープ (Volume Envelope) <a class="header-anchor" href="#_1-音量エンベロープ-volume-envelope" aria-label="Permalink to &quot;1. 音量エンベロープ (Volume Envelope)&quot;">​</a></h3><ul><li>再生中の音量変化を制御します。</li><li><strong>編集</strong>: 曲線上のポイントをクリックしてドラッグし、形状を変更します。</li><li><strong>用途</strong>: 複雑なフェードイン・フェードアウト、ビブラート、または徐々に減衰する効果を実現します。</li><li><strong>注意</strong>: 通常モードのフェード効果と高度なモードの音量エンベロープが同時に存在する場合、高度なモードの音量エンベロープが通常モードの設定を上書きします。</li></ul><h3 id="_2-音程エンベロープ-pitch-envelope" tabindex="-1">2. 音程エンベロープ (Pitch Envelope) <a class="header-anchor" href="#_2-音程エンベロープ-pitch-envelope" aria-label="Permalink to &quot;2. 音程エンベロープ (Pitch Envelope)&quot;">​</a></h3><ul><li>再生中の音程（ピッチ）のずれを制御します。</li><li><strong>編集</strong>: 上記と同様です。</li><li><strong>用途</strong>: ポルタメント、ピッチの揺れ、または特殊な音響効果を実現します。</li><li><strong>注意</strong>: 通常モードの音程設定と高度なモードの音程エンベロープが同時に存在する場合、高度なモードの音程エンベロープが通常モードの音程を上書きします。</li></ul><hr><h2 id="ダイナミック音源移動" tabindex="-1">ダイナミック音源移動 <a class="header-anchor" href="#ダイナミック音源移動" aria-label="Permalink to &quot;ダイナミック音源移動&quot;">​</a></h2><p>これは Extended Note Block の特徴的な機能であり、音が時間とともに空間内を「移動」することを可能にします。<strong>数式</strong> を入力することで、X、Y、Z 軸上での音源の相対的なオフセットを定義できます。</p><h3 id="変数の説明" tabindex="-1">変数の説明： <a class="header-anchor" href="#変数の説明" aria-label="Permalink to &quot;変数の説明：&quot;">​</a></h3><ul><li><code>t</code>: 現在の再生進行度の割合 (0.0 から 1.0)。</li><li><code>d</code>: 現在の再生時間、単位は Tick (1 Tick = 0.05 秒)。</li><li><code>pi</code>: 定数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>π</mi></mrow><annotation encoding="application/x-tex">\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03588em;">π</span></span></span></span> (約 3.14159)。</li></ul><h3 id="一般的な関数" tabindex="-1">一般的な関数： <a class="header-anchor" href="#一般的な関数" aria-label="Permalink to &quot;一般的な関数：&quot;">​</a></h3><p><code>sin</code>、<code>cos</code>、<code>tan</code>、<code>abs</code>、<code>sqrt</code>、<code>log</code>、<code>exp</code> などの標準的な数学関数をサポートしています。</p><h3 id="使用例" tabindex="-1">使用例： <a class="header-anchor" href="#使用例" aria-label="Permalink to &quot;使用例：&quot;">​</a></h3><ul><li><strong>円運動</strong>: <ul><li>X 軸: <code>5 * sin(2 * pi * t)</code></li><li>Z 軸: <code>5 * cos(2 * pi * t)</code></li><li><em>効果: 音源が Note Block を中心に半径 5 ブロックで回転します。</em></li></ul></li><li><strong>垂直上昇</strong>: <ul><li>Y 軸: <code>t * 10</code></li><li><em>効果: 再生に伴い、音が徐々に 10 ブロック上昇します。</em></li></ul></li><li><strong>サイン波による上下動</strong>: <ul><li>Y 軸: <code>sin(d * 0.5)</code></li><li><em>効果: 音が上下に揺れ動きます。</em></li></ul></li></ul><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>式の入力ボックスに赤い警告が表示された場合、構文に誤りがあることを意味します。</li></ul>',20)])])}const g=o(n,[["render",d]]);export{_ as __pageData,g as default};
